import{_ as l}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o as s,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"构建 Skills 最佳实践","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/skills/skills-best-practices.md","filePath":"zh/tech/skills/skills-best-practices.md","lastUpdated":1787042982000}'),e={name:"zh/tech/skills/skills-best-practices.md"};function n(r,a,o,h,p,d){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="构建-skills-最佳实践" tabindex="-1">构建 Skills 最佳实践 <a class="header-anchor" href="#构建-skills-最佳实践" aria-label="Permalink to &quot;构建 Skills 最佳实践&quot;">​</a></h1><blockquote><p>学习来源：<a href="https://claude.com/blog/how-to-create-skills-key-steps-limitations-and-examples" target="_blank" rel="noreferrer">https://claude.com/blog/how-to-create-skills-key-steps-limitations-and-examples</a></p></blockquote><h2 id="核心原则" tabindex="-1">核心原则 <a class="header-anchor" href="#核心原则" aria-label="Permalink to &quot;核心原则&quot;">​</a></h2><h3 id="_1-从真实用例出发" tabindex="-1">1. 从真实用例出发 <a class="header-anchor" href="#_1-从真实用例出发" aria-label="Permalink to &quot;1. 从真实用例出发&quot;">​</a></h3><p><strong>不要凭空构建 Skills</strong>。只有当有真实、重复的任务时才创建。</p><p><strong>自问清单</strong>：</p><ul><li>我至少做过 5 次这个任务了吗？</li><li>我还会再做至少 10 次吗？</li><li>这个任务有可衡量的成功标准吗？</li></ul><h3 id="_2-定义成功标准" tabindex="-1">2. 定义成功标准 <a class="header-anchor" href="#_2-定义成功标准" aria-label="Permalink to &quot;2. 定义成功标准&quot;">​</a></h3><p>告诉 Claude 好的输出是什么样的：</p><ul><li>必需包含哪些部分？</li><li>格式化标准是什么？</li><li>需要哪些验证检查？</li><li>质量阈值是多少？</li></ul><p>将这些标准包含在指令中，让 Claude 可以自我检查。</p><h3 id="_3-使用-skill-creator-skill" tabindex="-1">3. 使用 Skill-Creator Skill <a class="header-anchor" href="#_3-使用-skill-creator-skill" aria-label="Permalink to &quot;3. 使用 Skill-Creator Skill&quot;">​</a></h3><p><a href="https://github.com/anthropics/skills/tree/main/skill-creator" target="_blank" rel="noreferrer">skill-creator Skill</a> 会引导你创建结构良好的 Skills：</p><ul><li>提出澄清问题</li><li>建议描述改进</li><li>帮助正确格式化指令</li></ul><hr><h2 id="触发机制最佳实践" tabindex="-1">触发机制最佳实践 <a class="header-anchor" href="#触发机制最佳实践" aria-label="Permalink to &quot;触发机制最佳实践&quot;">​</a></h2><h3 id="编写有效描述" tabindex="-1">编写有效描述 <a class="header-anchor" href="#编写有效描述" aria-label="Permalink to &quot;编写有效描述&quot;">​</a></h3><p>描述是 Skill 激活的关键。从 Claude 的视角编写，聚焦于<strong>触发条件、能力和用例</strong>。</p><p><strong>四要素描述法</strong>：</p><ol><li><strong>具体能力</strong>：用动词描述（extract、create、merge、analyze）</li><li><strong>明确触发</strong>：什么情况下应激活？</li><li><strong>相关上下文</strong>：涉及什么类型的数据、工具、格式？</li><li><strong>清晰边界</strong>：不适合做什么？</li></ol><p><strong>示例对比</strong>：</p><p>❌ 泛化描述：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>This skill helps with PDFs.</span></span></code></pre></div><p>✅ 具体描述：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Comprehensive PDF manipulation toolkit for extracting text and tables, creating new PDFs, merging/splitting documents, and handling forms. When Claude needs to fill in a PDF form or programmatically process, generate, or analyze PDF documents at scale. Use for document workflows and batch operations. Not for simple PDF viewing or basic conversions.</span></span></code></pre></div><h3 id="粒度控制" tabindex="-1">粒度控制 <a class="header-anchor" href="#粒度控制" aria-label="Permalink to &quot;粒度控制&quot;">​</a></h3><p><strong>太泛化</strong>：→ &quot;Content marketing helper&quot;（不知道能做什么） <strong>太细化</strong>：→ &quot;Add meta descriptions to blog posts&quot;（复用性差） <strong>适中</strong>：→ &quot;SEO optimization for blog posts&quot;（明确且可复用）</p><h3 id="语义触发-vs-关键词匹配" tabindex="-1">语义触发 vs 关键词匹配 <a class="header-anchor" href="#语义触发-vs-关键词匹配" aria-label="Permalink to &quot;语义触发 vs 关键词匹配&quot;">​</a></h3><p>Claude 通过<strong>语义理解</strong>评估请求与 Skill 描述的相关性，不是简单的关键词匹配。这意味着：</p><ul><li>描述应该捕捉意图和场景</li><li>同义词和表达变体都能被理解</li><li>模糊描述会降低准确性</li></ul><hr><h2 id="渐进式加载最佳实践" tabindex="-1">渐进式加载最佳实践 <a class="header-anchor" href="#渐进式加载最佳实践" aria-label="Permalink to &quot;渐进式加载最佳实践&quot;">​</a></h2><h3 id="菜单-方式" tabindex="-1">&quot;菜单&quot;方式 <a class="header-anchor" href="#菜单-方式" aria-label="Permalink to &quot;&quot;菜单&quot;方式&quot;">​</a></h3><p>不要把所有内容塞进一个 SKILL.md。使用&quot;菜单&quot;方式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-skill/</span></span>
<span class="line"><span>├── SKILL.md          # 描述可用内容和入口</span></span>
<span class="line"><span>├── workflows/</span></span>
<span class="line"><span>│   ├── basic-workflow.md</span></span>
<span class="line"><span>│   └── advanced-workflow.md</span></span>
<span class="line"><span>├── templates/</span></span>
<span class="line"><span>│   └── report-template.md</span></span>
<span class="line"><span>└── scripts/</span></span>
<span class="line"><span>    └── processor.py</span></span></code></pre></div><p>SKILL.md 描述整体框架，详细内容在独立文件中。Claude 只在需要时读取相关文件。</p><h3 id="文件大小控制" tabindex="-1">文件大小控制 <a class="header-anchor" href="#文件大小控制" aria-label="Permalink to &quot;文件大小控制&quot;">​</a></h3><ul><li>避免用不必要的内容撑满上下文窗口</li><li>每次加载的信息应该是当时所需的最小集</li><li>使用引用（相对路径）而非内联所有内容</li></ul><hr><h2 id="指令编写最佳实践" tabindex="-1">指令编写最佳实践 <a class="header-anchor" href="#指令编写最佳实践" aria-label="Permalink to &quot;指令编写最佳实践&quot;">​</a></h2><h3 id="结构化指令" tabindex="-1">结构化指令 <a class="header-anchor" href="#结构化指令" aria-label="Permalink to &quot;结构化指令&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## Overview（概览）</span></span>
<span class="line"><span>## Prerequisites（前置条件）</span></span>
<span class="line"><span>## Execution Steps（执行步骤）</span></span>
<span class="line"><span>## Examples（示例）</span></span>
<span class="line"><span>## Error Handling（错误处理）</span></span>
<span class="line"><span>## Limitations（限制）</span></span></code></pre></div><h3 id="可执行代码规范" tabindex="-1">可执行代码规范 <a class="header-anchor" href="#可执行代码规范" aria-label="Permalink to &quot;可执行代码规范&quot;">​</a></h3><p>Skill 中包含的代码应该：</p><ul><li><strong>简洁</strong>：避免冗余变量和操作</li><li><strong>有示例</strong>：展示正确用法</li><li><strong>有边界检查</strong>：处理异常输入</li><li><strong>有错误处理</strong>：失败时有清晰的错误信息</li></ul><h3 id="包含反例" tabindex="-1">包含反例 <a class="header-anchor" href="#包含反例" aria-label="Permalink to &quot;包含反例&quot;">​</a></h3><p>展示什么是<strong>错误</strong>的做法：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># BAD - Replaces entire sentence</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;w:del&gt;...&lt;/w:del&gt;&lt;w:ins&gt;...&lt;/w:ins&gt;&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># GOOD - Only marks what changed</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;w:r&gt;...&lt;/w:r&gt;&lt;w:del&gt;...&lt;/w:del&gt;&lt;w:ins&gt;...&lt;/w:ins&gt;&#39;</span></span></code></pre></div><hr><h2 id="测试最佳实践" tabindex="-1">测试最佳实践 <a class="header-anchor" href="#测试最佳实践" aria-label="Permalink to &quot;测试最佳实践&quot;">​</a></h2><h3 id="测试矩阵" tabindex="-1">测试矩阵 <a class="header-anchor" href="#测试矩阵" aria-label="Permalink to &quot;测试矩阵&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景类型</th><th>测试内容</th><th>示例</th></tr></thead><tbody><tr><td>正常操作</td><td>Skill 应完美处理的典型请求</td><td>&quot;用财务数据包分析这家公司&quot;</td></tr><tr><td>边缘情况</td><td>不完整或意外的输入</td><td>数据缺失、格式异常</td></tr><tr><td>越界请求</td><td>看起来相关但不应触发的任务</td><td>NDA Skill 收到租约分析请求</td></tr></tbody></table><h3 id="触发测试" tabindex="-1">触发测试 <a class="header-anchor" href="#触发测试" aria-label="Permalink to &quot;触发测试&quot;">​</a></h3><ul><li><strong>正向测试</strong>： <ul><li>显式请求：&quot;使用财务数据包分析这家公司&quot;（应触发）</li><li>自然请求：&quot;帮我理解这家公司的财务状况&quot;（应触发）</li></ul></li><li><strong>负向测试</strong>： <ul><li>相似的邻近请求能保持沉默吗？</li><li>边界是否清晰？</li></ul></li></ul><h3 id="功能测试" tabindex="-1">功能测试 <a class="header-anchor" href="#功能测试" aria-label="Permalink to &quot;功能测试&quot;">​</a></h3><ul><li><strong>输出一致性</strong>：相同输入多次运行结果相似吗？</li><li><strong>可用性</strong>：不熟悉该领域的人能成功使用吗？</li><li><strong>文档准确性</strong>：示例与实际行为匹配吗？</li></ul><hr><h2 id="组织内共享最佳实践" tabindex="-1">组织内共享最佳实践 <a class="header-anchor" href="#组织内共享最佳实践" aria-label="Permalink to &quot;组织内共享最佳实践&quot;">​</a></h2><h3 id="小团队" tabindex="-1">小团队 <a class="header-anchor" href="#小团队" aria-label="Permalink to &quot;小团队&quot;">​</a></h3><p>创建共享文档仓库，包含：</p><ul><li>Skill 规范模板（名称、描述、指令、版本）</li><li>所有 Skill 的集中索引</li><li>使用示例和常见问题</li></ul><h3 id="中大型团队" tabindex="-1">中大型团队 <a class="header-anchor" href="#中大型团队" aria-label="Permalink to &quot;中大型团队&quot;">​</a></h3><p>建立 Skills 治理流程：</p><ul><li><strong>指定 Skill 负责人</strong>：每个领域（财务、法务、市场）有负责人</li><li><strong>维护中心知识库</strong>：作为 Skill 库</li><li><strong>使用指南和排错</strong>：每个 Skill 附带</li><li><strong>版本控制和变更日志</strong>：追踪变更历史</li><li><strong>季度评审</strong>：更新或淘汰过时 Skills</li></ul><h3 id="所有团队规模通用" tabindex="-1">所有团队规模通用 <a class="header-anchor" href="#所有团队规模通用" aria-label="Permalink to &quot;所有团队规模通用&quot;">​</a></h3><ul><li>记录每个 Skill 的业务目的</li><li>指定明确的维护和更新负责人</li><li>创建新人 onboarding 材料</li><li>追踪哪些 Skills 最有价值以优先维护</li><li>使用一致的命名约定便于搜索</li></ul><hr><h2 id="常见陷阱与避免" tabindex="-1">常见陷阱与避免 <a class="header-anchor" href="#常见陷阱与避免" aria-label="Permalink to &quot;常见陷阱与避免&quot;">​</a></h2><h3 id="陷阱-1-过度工程化" tabindex="-1">陷阱 1：过度工程化 <a class="header-anchor" href="#陷阱-1-过度工程化" aria-label="Permalink to &quot;陷阱 1：过度工程化&quot;">​</a></h3><p><strong>问题</strong>：为从未遇到的场景构建复杂的边缘处理 <strong>解决</strong>：从实际遇到的用例出发，逐步迭代</p><h3 id="陷阱-2-描述过于宽泛" tabindex="-1">陷阱 2：描述过于宽泛 <a class="header-anchor" href="#陷阱-2-描述过于宽泛" aria-label="Permalink to &quot;陷阱 2：描述过于宽泛&quot;">​</a></h3><p><strong>问题</strong>：&quot;This skill helps with code&quot; 这样的描述无法有效触发 <strong>解决</strong>：具体说明能力、触发条件和边界</p><h3 id="陷阱-3-把所有内容塞进一个文件" tabindex="-1">陷阱 3：把所有内容塞进一个文件 <a class="header-anchor" href="#陷阱-3-把所有内容塞进一个文件" aria-label="Permalink to &quot;陷阱 3：把所有内容塞进一个文件&quot;">​</a></h3><p><strong>问题</strong>：大文件污染上下文窗口 <strong>解决</strong>：使用渐进式加载，SKILL.md 只做索引</p><h3 id="陷阱-4-忽略越界场景" tabindex="-1">陷阱 4：忽略越界场景 <a class="header-anchor" href="#陷阱-4-忽略越界场景" aria-label="Permalink to &quot;陷阱 4：忽略越界场景&quot;">​</a></h3><p><strong>问题</strong>：Skill 对不该处理的任务也激活 <strong>解决</strong>：在描述中明确边界，测试越界场景</p><h3 id="陷阱-5-不做测试" tabindex="-1">陷阱 5：不做测试 <a class="header-anchor" href="#陷阱-5-不做测试" aria-label="Permalink to &quot;陷阱 5：不做测试&quot;">​</a></h3><p><strong>问题</strong>：部署后发现行为不符合预期 <strong>解决</strong>：构建测试矩阵，覆盖正常、边缘和越界场景</p><hr><h2 id="迭代与改进" tabindex="-1">迭代与改进 <a class="header-anchor" href="#迭代与改进" aria-label="Permalink to &quot;迭代与改进&quot;">​</a></h2><p>Skill 发布后的生命周期：</p><ol><li><strong>监控</strong>：观察 Skill 在真实使用中的表现</li><li><strong>收集反馈</strong>：用户是否遇到问题？哪里不清楚？</li><li><strong>迭代描述</strong>：如果触发不一致 → 改进描述</li><li><strong>迭代指令</strong>：如果输出不稳定 → 添加具体性和验证步骤</li><li><strong>扩展能力</strong>：根据需要添加新功能</li></ol><p><strong>原则</strong>：最好的 Skills 是通过实践迭代演进的。不要期望第一版就完美。</p><hr><h2 id="参考资源" tabindex="-1">参考资源 <a class="header-anchor" href="#参考资源" aria-label="Permalink to &quot;参考资源&quot;">​</a></h2><ul><li><a href="https://github.com/anthropics/skills" target="_blank" rel="noreferrer">Anthropic Skills 仓库</a></li><li><a href="https://github.com/anthropics/skills/tree/main/skill-creator" target="_blank" rel="noreferrer">Skill-Creator 模板</a></li><li><a href="https://support.claude.com/en/articles/12512176-what-are-skills" target="_blank" rel="noreferrer">Skills 官方文档</a></li><li><a href="https://platform.claude.com/cookbook/skills-notebooks-01-skills-introduction" target="_blank" rel="noreferrer">Skills Cookbook</a></li></ul>`,86)])])}const m=l(e,[["render",n]]);export{b as __pageData,m as default};
